code_example:
// Regular initialization with auto deduces int
auto x1 = 42;
auto x2(42);

// Braced initialization with auto deduces std::initializer_list<int>
auto x3 = {42}; // type is std::initializer_list<int>

// For multiple elements, the deduction is also std::initializer_list
auto x4 = {1, 2, 3}; // type is std::initializer_list<int>
